1	import { useState, useMemo } from "react";
2	import {
3	  Dialog,
4	  DialogContent,
5	  DialogDescription,
6	  DialogHeader,
7	  DialogTitle,
8	} from "@/components/ui/dialog";
9	import { Button } from "@/components/ui/button";
10	import { Input } from "@/components/ui/input";
11	import { Label } from "@/components/ui/label";
12	import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
13	import { ScrollArea } from "@/components/ui/scroll-area";
14	import { Separator } from "@/components/ui/separator";
15	import {
16	  Select,
17	  SelectContent,
18	  SelectItem,
19	  SelectTrigger,
20	  SelectValue,
21	} from "@/components/ui/select";
22	import {
23	  Copy,
24	  Check,
25	  Link2,
26	  Globe,
27	  Mail,
28	  UserPlus,
29	  Trash2,
30	  Shield,
31	  Loader2,
32	} from "lucide-react";
33	import { useToast } from "@/hooks/use-toast";
34	import { useListShares, useCreateShare, useUpdateShare, useRemoveShare } from "@/hooks/use-collaboration";
35	import { ROLE_LABELS, type ProjectRole } from "@/lib/collaboration-types";
36	import { Switch } from "@/components/ui/switch";
37	
38	interface ShareDialogProps {
39	  open: boolean;
40	  onOpenChange: (open: boolean) => void;
41	  projectId: number;
42	  projectName?: string;
43	  canManage?: boolean;
44	}
45	
46	export function ShareDialog({
47	  open,
48	  onOpenChange,
49	  projectId,
50	  projectName,
51	  canManage = true,
52	}: ShareDialogProps) {
53	  const { toast } = useToast();
54	  const [copied, setCopied] = useState(false);
55	  const [inviteEmail, setInviteEmail] = useState("");
56	  const [inviteRole, setInviteRole] = useState<ProjectRole>("viewer");
57	  const [publicLinkEnabled, setPublicLinkEnabled] = useState(false);
58	  const [publicRole, setPublicRole] = useState<ProjectRole>("viewer");
59	
60	  const shareUrl =
61	    typeof window !== "undefined"
62	      ? `${window.location.origin}/project/${projectId}`
63	      : `/project/${projectId}`;
64	
65	  const { data: shares, isLoading } = useListShares(projectId);
66	  const createShare = useCreateShare();
67	  const updateShare = useUpdateShare();
68	  const removeShare = useRemoveShare();
69	
70	  const handleCopy = async () => {
71	    try {
72	      await navigator.clipboard.writeText(shareUrl);
73	      setCopied(true);
74	      toast({ title: "Link copied to clipboard" });
75	      setTimeout(() => setCopied(false), 2000);
76	    } catch {
77	      toast({ title: "Could not copy link", variant: "destructive" });
78	    }
79	  };
80	
81	  const handleInvite = async (e: React.FormEvent) => {
82	    e.preventDefault();
83	    if (!inviteEmail.trim()) return;
84	    try {
85	      await createShare.mutateAsync({ projectId, email: inviteEmail.trim(), role: inviteRole });
86	      setInviteEmail("");
87	      toast({ title: "Invitation sent" });
88	    } catch (err) {
89	      toast({ title: "Invite failed", description: err instanceof Error ? err.message : String(err), variant: "destructive" });
90	    }
91	  };
92	
93	  const handleRoleChange = async (shareId: number, role: ProjectRole) => {
94	    try {
95	      await updateShare.mutateAsync({ projectId, shareId, role });
96	      toast({ title: "Permission updated" });
97	    } catch (err) {
98	      toast({ title: "Update failed", description: err instanceof Error ? err.message : String(err), variant: "destructive" });
99	    }
100	  };
101	
102	  const handleRemove = async (shareId: number) => {
103	    try {
104	      await removeShare.mutateAsync({ projectId, shareId });
105	      toast({ title: "Access removed" });
106	    } catch (err) {
107	      toast({ title: "Remove failed", description: err instanceof Error ? err.message : String(err), variant: "destructive" });
108	    }
109	  };
110	
111	  const roleOptions: ProjectRole[] = ["admin", "editor", "commenter", "viewer"];
112	
113	  const members = useMemo(() => shares?.filter((s) => s.user) ?? [], [shares]);
114	  const pending = useMemo(() => shares?.filter((s) => !s.user && s.email) ?? [], [shares]);
115	
116	  return (
117	    <Dialog open={open} onOpenChange={onOpenChange}>
118	      <DialogContent className="sm:max-w-lg max-h-[85vh] flex flex-col">
119	        <DialogHeader>
120	          <DialogTitle className="flex items-center gap-2">
121	            <ShareIcon className="h-5 w-5" />
122	            Share {projectName ? `"${projectName}"` : "project"}
123	          </DialogTitle>
124	          <DialogDescription>
125	            Manage who can access this project and what they can do.
126	          </DialogDescription>
127	        </DialogHeader>
128	
129	        <div className="flex flex-col gap-5 overflow-hidden">
130	          {canManage && (
131	            <>
132	              <form onSubmit={handleInvite} className="flex items-end gap-2">
133	                <div className="flex-1 space-y-1.5">
134	                  <Label htmlFor="invite-email" className="flex items-center gap-1.5">
135	                    <Mail className="h-3.5 w-3.5" /> Invite by email
136	                  </Label>
137	                  <Input
138	                    id="invite-email"
139	                    type="email"
140	                    placeholder="teammate@example.com"
141	                    value={inviteEmail}
142	                    onChange={(e) => setInviteEmail(e.target.value)}
143	                    disabled={createShare.isPending}
144	                  />
145	                </div>
146	                <Select value={inviteRole} onValueChange={(v) => setInviteRole(v as ProjectRole)}>
147	                  <SelectTrigger className="w-[130px]">
148	                    <SelectValue />
149	                  </SelectTrigger>
150	                  <SelectContent>
151	                    {roleOptions.map((r) => (
152	                      <SelectItem key={r} value={r}>{ROLE_LABELS[r]}</SelectItem>
153	                    ))}
154	                  </SelectContent>
155	                </Select>
156	                <Button type="submit" disabled={!inviteEmail.trim() || createShare.isPending}>
157	                  {createShare.isPending ? <Loader2 className="h-4 w-4 animate-spin" /> : <UserPlus className="h-4 w-4" />}
158	                </Button>
159	              </form>
160	
161	              <div className="rounded-md border bg-muted/30 p-3 space-y-3">
162	                <div className="flex items-center gap-2 text-sm font-medium">
163	                  <Globe className="h-4 w-4 text-primary" /> Public link
164	                </div>
165	                <div className="flex items-center justify-between">
166	                  <div className="space-y-0.5">
167	                    <Label className="text-xs">Allow anyone with the link to access</Label>
168	                    <p className="text-[10px] text-muted-foreground">No sign-in required</p>
169	                  </div>
170	                  <Switch checked={publicLinkEnabled} onCheckedChange={setPublicLinkEnabled} />
171	                </div>
172	                {publicLinkEnabled && (
173	                  <>
174	                    <Select value={publicRole} onValueChange={(v) => setPublicRole(v as ProjectRole)}>
175	                      <SelectTrigger className="w-full text-xs">
176	                        <SelectValue placeholder="Permission level" />
177	                      </SelectTrigger>
178	                      <SelectContent>
179	                        {roleOptions.map((r) => (
180	                          <SelectItem key={r} value={r}>{ROLE_LABELS[r]}</SelectItem>
181	                        ))}
182	                      </SelectContent>
183	                    </Select>
184	                    <div className="flex items-center gap-2">
185	                      <Input readOnly value={shareUrl} className="text-xs font-mono bg-background" />
186	                      <Button size="icon" variant="outline" onClick={handleCopy}>
187	                        {copied ? <Check className="h-4 w-4 text-green-500" /> : <Copy className="h-4 w-4" />}
188	                      </Button>
189	                    </div>
190	                  </>
191	                )}
192	              </div>
193	            </>
194	          )}
195	
196	          <Separator />
197	
198	          <div className="space-y-2 min-h-0 flex flex-col">
199	            <Label className="text-xs uppercase tracking-wider text-muted-foreground">
200	              People with access
201	            </Label>
202	            <ScrollArea className="flex-1 -mx-1 px-1">
203	              {isLoading ? (
204	                <div className="space-y-2 py-2">
205	                  {[1, 2].map((i) => (
206	                    <div key={i} className="flex items-center gap-3 animate-pulse">
207	                      <div className="w-8 h-8 rounded-full bg-muted" />
208	                      <div className="flex-1 h-4 bg-muted rounded" />
209	                    </div>
210	                  ))}
211	                </div>
212	              ) : (
213	                <div className="space-y-1 py-1">
214	                  {members.map((share) => {
215	                    const display = [share.user!.firstName, share.user!.lastName].filter(Boolean).join(" ") || share.user!.email || "User";
216	                    const initial = (display[0] ?? "?").toUpperCase();
217	                    const isOwner = share.role === "owner";
218	                    return (
219	                      <div key={share.id} className="flex items-center gap-3 p-2 rounded hover:bg-muted/50 transition-colors">
220	                        <Avatar className="h-8 w-8">
221	                          {share.user!.imageUrl && <AvatarImage src={share.user!.imageUrl} alt="" />}
222	                          <AvatarFallback className="text-xs">{initial}</AvatarFallback>
223	                        </Avatar>
224	                        <div className="flex-1 min-w-0">
225	                          <div className="text-sm font-medium truncate">{display}</div>
226	                          <div className="text-[10px] text-muted-foreground truncate">{share.user!.email}</div>
227	                        </div>
228	                        {isOwner ? (
229	                          <span className="text-[10px] uppercase tracking-wide text-muted-foreground flex items-center gap-1">
230	                            <Shield className="h-3 w-3" /> Owner
231	                          </span>
232	                        ) : canManage ? (
233	                          <div className="flex items-center gap-1">
234	                            <Select
235	                              value={share.role}
236	                              onValueChange={(v) => handleRoleChange(share.id, v as ProjectRole)}
237	                            >
238	                              <SelectTrigger className="h-7 text-[10px] w-[110px]">
239	                                <SelectValue />
240	                              </SelectTrigger>
241	                              <SelectContent>
242	                                {roleOptions.map((r) => (
243	                                  <SelectItem key={r} value={r}>{ROLE_LABELS[r]}</SelectItem>
244	                                ))}
245	                              </SelectContent>
246	                            </Select>
247	                            <Button
248	                              size="icon"
249	                              variant="ghost"
250	                              className="h-7 w-7 text-muted-foreground hover:text-destructive"
251	                              onClick={() => handleRemove(share.id)}
252	                              disabled={removeShare.isPending}
253	                            >
254	                              <Trash2 className="h-3.5 w-3.5" />
255	                            </Button>
256	                          </div>
257	                        ) : (
258	                          <span className="text-[10px] uppercase tracking-wide text-muted-foreground">{ROLE_LABELS[share.role]}</span>
259	                        )}
260	                      </div>
261	                    );
262	                  })}
263	                  {pending.map((share) => (
264	                    <div key={share.id} className="flex items-center gap-3 p-2 rounded hover:bg-muted/50 transition-colors opacity-70">
265	                      <div className="w-8 h-8 rounded-full bg-muted flex items-center justify-center">
266	                        <Mail className="h-4 w-4 text-muted-foreground" />
267	                      </div>
268	                      <div className="flex-1 min-w-0">
269	                        <div className="text-sm font-medium truncate">{share.email}</div>
270	                        <div className="text-[10px] text-muted-foreground">Pending invitation</div>
271	                      </div>
272	                      <span className="text-[10px] uppercase tracking-wide text-muted-foreground">{ROLE_LABELS[share.role]}</span>
273	                      {canManage && (
274	                        <Button
275	                          size="icon"
276	                          variant="ghost"
277	                          className="h-7 w-7 text-muted-foreground hover:text-destructive"
278	                          onClick={() => handleRemove(share.id)}
279	                        >
280	                          <Trash2 className="h-3.5 w-3.5" />
281	                        </Button>
282	                      )}
283	                    </div>
284	                  ))}
285	                  {members.length === 0 && pending.length === 0 && (
286	                    <div className="text-sm text-muted-foreground text-center py-4">No one has access yet.</div>
287	                  )}
288	                </div>
289	              )}
290	            </ScrollArea>
291	          </div>
292	        </div>
293	      </DialogContent>
294	    </Dialog>
295	  );
296	}
297	
298	function ShareIcon({ className }: { className?: string }) {
299	  return (
300	    <svg
301	      xmlns="http://www.w3.org/2000/svg"
302	      viewBox="0 0 24 24"
303	      fill="none"
304	      stroke="currentColor"
305	      strokeWidth="2"
306	      strokeLinecap="round"
307	      strokeLinejoin="round"
308	      className={className}
309	    >
310	      <circle cx="18" cy="5" r="3" />
311	      <circle cx="6" cy="12" r="3" />
312	      <circle cx="18" cy="19" r="3" />
313	      <line x1="8.59" y1="13.51" x2="15.42" y2="17.49" />
314	      <line x1="15.41" y1="6.51" x2="8.59" y2="10.49" />
315	    </svg>
316	  );
317	}
