1	import { useState } from "react";
2	import { Button } from "@/components/ui/button";
3	import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
4	import { Badge } from "@/components/ui/badge";
5	import { ScrollArea } from "@/components/ui/scroll-area";
6	import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
7	import { Skeleton } from "@/components/ui/skeleton";
8	import { Separator } from "@/components/ui/separator";
9	import {
10	  Bell,
11	  MessageSquare,
12	  UserCheck,
13	  AlertTriangle,
14	  CheckCheck,
15	  Trash2,
16	  AtSign,
17	  GitCommit,
18	  X,
19	} from "lucide-react";
20	import {
21	  useListNotifications,
22	  useMarkNotificationRead,
23	  useMarkAllNotificationsRead,
24	  useDeleteNotification,
25	} from "@/hooks/use-collaboration";
26	import { formatDistanceToNow } from "date-fns";
27	import type { NotificationItem } from "@/lib/collaboration-types";
28	
29	export function NotificationBell() {
30	  const [open, setOpen] = useState(false);
31	  const { data: notifications, isLoading } = useListNotifications();
32	  const markRead = useMarkNotificationRead();
33	  const markAll = useMarkAllNotificationsRead();
34	  const del = useDeleteNotification();
35	
36	  const unreadCount = notifications?.filter((n) => !n.read).length ?? 0;
37	
38	  const handleMarkRead = async (id: string) => {
39	    await markRead.mutateAsync(id);
40	  };
41	
42	  const handleMarkAll = async () => {
43	    await markAll.mutateAsync();
44	  };
45	
46	  const handleDelete = async (id: string) => {
47	    await del.mutateAsync(id);
48	  };
49	
50	  return (
51	    <Popover open={open} onOpenChange={setOpen}>
52	      <PopoverTrigger asChild>
53	        <Button variant="ghost" size="icon" className="relative h-9 w-9">
54	          <Bell className="h-5 w-5" />
55	          {unreadCount > 0 && (
56	            <Badge
57	              variant="destructive"
58	              className="absolute -top-1 -right-1 h-5 w-5 flex items-center justify-center p-0 text-[10px]"
59	            >
60	              {unreadCount > 9 ? "9+" : unreadCount}
61	            </Badge>
62	          )}
63	        </Button>
64	      </PopoverTrigger>
65	      <PopoverContent className="w-96 p-0" align="end">
66	        <div className="flex items-center justify-between px-4 py-3 border-b">
67	          <h3 className="text-sm font-semibold">Notifications</h3>
68	          <div className="flex items-center gap-1">
69	            {unreadCount > 0 && (
70	              <Button
71	                variant="ghost"
72	                size="sm"
73	                className="h-7 text-xs"
74	                onClick={handleMarkAll}
75	                disabled={markAll.isPending}
76	              >
77	                <CheckCheck className="h-3.5 w-3.5 mr-1" /> Mark all read
78	              </Button>
79	            )}
80	          </div>
81	        </div>
82	        <ScrollArea className="h-[320px]">
83	          {isLoading ? (
84	            <div className="space-y-3 p-4">
85	              {[1, 2, 3].map((i) => (
86	                <div key={i} className="flex gap-3">
87	                  <Skeleton className="h-8 w-8 rounded-full shrink-0" />
88	                  <div className="flex-1 space-y-2">
89	                    <Skeleton className="h-3 w-3/4" />
90	                    <Skeleton className="h-3 w-1/2" />
91	                  </div>
92	                </div>
93	              ))}
94	            </div>
95	          ) : !notifications || notifications.length === 0 ? (
96	            <div className="flex flex-col items-center justify-center py-8 text-muted-foreground">
97	              <Bell className="h-8 w-8 mb-2 opacity-50" />
98	              <p className="text-sm">No notifications yet</p>
99	            </div>
100	          ) : (
101	            <div className="divide-y">
102	              {notifications.map((notification) => (
103	                <NotificationItemRow
104	                  key={notification.id}
105	                  notification={notification}
106	                  onMarkRead={handleMarkRead}
107	                  onDelete={handleDelete}
108	                  isMarking={markRead.isPending}
109	                  isDeleting={del.isPending}
110	                />
111	              ))}
112	            </div>
113	          )}
114	        </ScrollArea>
115	        <Separator />
116	        <div className="px-4 py-2 text-center">
117	          <Button variant="ghost" size="sm" className="text-xs text-muted-foreground h-auto py-1">
118	            View all notifications
119	          </Button>
120	        </div>
121	      </PopoverContent>
122	    </Popover>
123	  );
124	}
125	
126	function NotificationItemRow({
127	  notification,
128	  onMarkRead,
129	  onDelete,
130	  isMarking,
131	  isDeleting,
132	}: {
133	  notification: NotificationItem;
134	  onMarkRead: (id: string) => void;
135	  onDelete: (id: string) => void;
136	  isMarking: boolean;
137	  isDeleting: boolean;
138	}) {
139	  const icon = getNotificationIcon(notification.type);
140	  const initial = (notification.actor?.firstName?.[0] ?? notification.actor?.email?.[0] ?? "?").toUpperCase();
141	
142	  return (
143	    <div
144	      className={`flex gap-3 p-3 transition-colors hover:bg-muted/50 ${
145	        !notification.read ? "bg-primary/5" : ""
146	      }`}
147	    >
148	      <div className="shrink-0">
149	        {notification.actor ? (
150	          <Avatar className="h-8 w-8">
151	            {notification.actor.imageUrl && <AvatarImage src={notification.actor.imageUrl} alt="" />}
152	            <AvatarFallback className="text-xs">{initial}</AvatarFallback>
153	          </Avatar>
154	        ) : (
155	          <div className="h-8 w-8 rounded-full bg-muted flex items-center justify-center">
156	            <icon.icon className={`h-4 w-4 ${icon.color}`} />
157	          </div>
158	        )}
159	      </div>
160	      <div className="flex-1 min-w-0">
161	        <div className="flex items-start justify-between gap-2">
162	          <div>
163	            <p className="text-sm leading-snug">
164	              <span className="font-medium">{notification.title}</span>
165	            </p>
166	            <p className="text-xs text-muted-foreground mt-0.5">{notification.message}</p>
167	            <p className="text-[10px] text-muted-foreground mt-1">
168	              {formatDistanceToNow(new Date(notification.createdAt), { addSuffix: true })}
169	            </p>
170	          </div>
171	          <div className="flex flex-col gap-1 shrink-0">
172	            {!notification.read && (
173	              <Button
174	                variant="ghost"
175	                size="icon"
176	                className="h-6 w-6"
177	                onClick={() => onMarkRead(notification.id)}
178	                disabled={isMarking}
179	              >
180	                <CheckCheck className="h-3.5 w-3.5" />
181	              </Button>
182	            )}
183	            <Button
184	              variant="ghost"
185	              size="icon"
186	              className="h-6 w-6 text-muted-foreground hover:text-destructive"
187	              onClick={() => onDelete(notification.id)}
188	              disabled={isDeleting}
189	            >
190	              <X className="h-3.5 w-3.5" />
191	            </Button>
192	          </div>
193	        </div>
194	      </div>
195	    </div>
196	  );
197	}
198	
199	function getNotificationIcon(type: NotificationItem["type"]) {
200	  switch (type) {
201	    case "comment":
202	      return { icon: MessageSquare, color: "text-blue-400" };
203	    case "mention":
204	      return { icon: AtSign, color: "text-purple-400" };
205	    case "assignment":
206	      return { icon: UserCheck, color: "text-green-400" };
207	    case "status_change":
208	      return { icon: GitCommit, color: "text-cyan-400" };
209	    case "due_soon":
210	      return { icon: AlertTriangle, color: "text-amber-400" };
211	    default:
212	      return { icon: Bell, color: "text-muted-foreground" };
213	  }
214	}
