1	import { useState } from "react";
2	import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
3	import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
4	import { ScrollArea } from "@/components/ui/scroll-area";
5	import { Skeleton } from "@/components/ui/skeleton";
6	import { Activity, MessageSquare, ArrowRight, Plus, Trash2, Pencil, UserPlus, GitCommit } from "lucide-react";
7	import { useListActivity } from "@/hooks/use-collaboration";
8	import { formatDistanceToNow } from "date-fns";
9	import type { ActivityLogEntry, ActivityAction } from "@/lib/collaboration-types";
10	
11	interface ActivityFeedProps {
12	  projectId: number;
13	  limit?: number;
14	}
15	
16	const ACTION_CONFIG: Record<ActivityAction, { icon: typeof Plus; label: string; color: string }> = {
17	  created: { icon: Plus, label: "created", color: "text-green-400 bg-green-500/10" },
18	  updated: { icon: Pencil, label: "updated", color: "text-blue-400 bg-blue-500/10" },
19	  deleted: { icon: Trash2, label: "deleted", color: "text-red-400 bg-red-500/10" },
20	  commented: { icon: MessageSquare, label: "commented on", color: "text-purple-400 bg-purple-500/10" },
21	  assigned: { icon: UserPlus, label: "assigned", color: "text-amber-400 bg-amber-500/10" },
22	  moved: { icon: ArrowRight, label: "moved", color: "text-cyan-400 bg-cyan-500/10" },
23	  joined: { icon: UserPlus, label: "joined", color: "text-green-400 bg-green-500/10" },
24	  shared: { icon: GitCommit, label: "shared", color: "text-indigo-400 bg-indigo-500/10" },
25	};
26	
27	export function ActivityFeed({ projectId, limit = 50 }: ActivityFeedProps) {
28	  const [filter, setFilter] = useState<ActivityAction | "all">("all");
29	  const { data: activity, isLoading } = useListActivity(projectId, limit);
30	
31	  const filtered = filter === "all" ? activity : activity?.filter((a) => a.action === filter);
32	  const actions = Array.from(new Set(activity?.map((a) => a.action) ?? []));
33	
34	  return (
35	    <Card className="flex flex-col h-full">
36	      <CardHeader className="pb-3">
37	        <CardTitle className="text-lg flex items-center gap-2">
38	          <Activity className="h-4 w-4" /> Activity Feed
39	        </CardTitle>
