1	import { useState, useRef, useEffect, useCallback } from "react";
2	import { Textarea } from "@/components/ui/textarea";
3	import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
4	
5	export interface MentionableUser {
6	  userId: string;
7	  userName: string;
8	  avatarUrl?: string;
9	}
10	
11	interface MentionInputProps {
12	  value: string;
13	  onChange: (value: string) => void;
14	  placeholder?: string;
15	  users?: MentionableUser[];
16	  disabled?: boolean;
17	  rows?: number;
18	}
19	
20	export function MentionInput({
21	  value,
22	  onChange,
23	  placeholder,
24	  users = [],
25	  disabled,
26	  rows = 3,
27	}: MentionInputProps) {
28	  const textareaRef = useRef<HTMLTextAreaElement>(null);
29	  const [showDropdown, setShowDropdown] = useState(false);
30	  const [query, setQuery] = useState("");
31	  const [cursorIndex, setCursorIndex] = useState(0);
32	  const [selectedIndex, setSelectedIndex] = useState(0);
33	
34	  const matches = users.filter((u) =>
35	    u.userName.toLowerCase().includes(query.toLowerCase())
36	  );
37	
38	  useEffect(() => {
39	    setSelectedIndex(0);
40	  }, [matches.length]);
41	
42	  const getMentionContext = useCallback((text: string, cursor: number) => {
43	    const before = text.slice(0, cursor);
44	    const atIdx = before.lastIndexOf("@");
45	    if (atIdx === -1) return null;
46	    const afterAt = before.slice(atIdx + 1);
47	    if (afterAt.includes(" ") || afterAt.includes("\n")) return null;
48	    return { start: atIdx, query: afterAt };
49	  }, []);
50	
51	  const handleChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
52	    const newValue = e.target.value;
53	    const cursor = e.target.selectionStart ?? newValue.length;
54	    onChange(newValue);
55	
56	    const ctx = getMentionContext(newValue, cursor);
57	    if (ctx) {
58	      setQuery(ctx.query);
59	      setCursorIndex(cursor);
60	      setShowDropdown(true);
61	    } else {
62	      setShowDropdown(false);
63	    }
64	  };
65	
66	  const insertMention = (user: MentionableUser) => {
67	    const ctx = getMentionContext(value, cursorIndex);
68	    if (!ctx) return;
69	    const before = value.slice(0, ctx.start);
70	    const after = value.slice(cursorIndex);
71	    const newValue = `${before}@${user.userName} ${after}`;
72	    onChange(newValue);
73	    setShowDropdown(false);
74	    setTimeout(() => {
75	      textareaRef.current?.focus();
76	      const pos = before.length + user.userName.length + 2;
77	      textareaRef.current?.setSelectionRange(pos, pos);
78	    }, 0);
79	  };
80	
81	  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
82	    if (!showDropdown || matches.length === 0) return;
83	    if (e.key === "ArrowDown") {
84	      e.preventDefault();
85	      setSelectedIndex((i) => (i + 1) % matches.length);
86	    } else if (e.key === "ArrowUp") {
87	      e.preventDefault();
88	      setSelectedIndex((i) => (i - 1 + matches.length) % matches.length);
89	    } else if (e.key === "Enter" || e.key === "Tab") {
90	      e.preventDefault();
91	      insertMention(matches[selectedIndex]);
92	    } else if (e.key === "Escape") {
93	      setShowDropdown(false);
94	    }
95	  };
96	
97	  return (
98	    <div className="relative">
99	      <Textarea
100	        ref={textareaRef}
101	        value={value}
102	        onChange={handleChange}
103	        onKeyDown={handleKeyDown}
104	        placeholder={placeholder}
105	        disabled={disabled}
106	        rows={rows}
107	        className="resize-none"
108	      />
109	      {showDropdown && matches.length > 0 && (
110	        <div className="absolute z-50 left-0 right-0 mt-1 max-h-52 overflow-y-auto rounded-md border bg-popover p-1 shadow-md text-sm">
111	          {matches.map((u, i) => {
112	            const initial = (u.userName[0] ?? "?").toUpperCase();
113	            return (
114	              <button
115	                key={u.userId}
116	                type="button"
117	                className={`w-full flex items-center gap-2 rounded-sm px-2 py-1.5 text-left hover:bg-accent ${
118	                  i === selectedIndex ? "bg-accent" : ""
119	                }`}
120	                onClick={() => insertMention(u)}
121	                onMouseEnter={() => setSelectedIndex(i)}
122	              >
123	                <Avatar className="h-5 w-5">
124	                  {u.avatarUrl && <AvatarImage src={u.avatarUrl} alt={u.userName} />}
125	                  <AvatarFallback className="text-[9px]">{initial}</AvatarFallback>
126	                </Avatar>
127	                <span className="truncate">{u.userName}</span>
128	              </button>
129	            );
130	          })}
131	        </div>
132	      )}
133	    </div>
134	  );
135	}
136	
137	export function parseCommentMentions(
138	  content: string,
139	): { userIds: string[]; contentWithLinks: string } {
140	  const mentionRegex = /@(\w+(?:\s+\w+)*)/g;
141	  const userIds: string[] = [];
142	  const contentWithLinks = content.replace(mentionRegex, (match, name) => {
143	    return `<span class="text-primary font-medium">${match}</span>`;
144	  });
145	  return { userIds, contentWithLinks };
146	}
