1	import { useState, useEffect, useCallback } from "react";
2	
3	export interface Notification {
4	  id: string;
5	  type: "comment" | "mention" | "assignment" | "system";
6	  title: string;
7	  message: string;
8	  projectId?: number;
9	  projectName?: string;
10	  userId?: string;
11	  userName?: string;
12	  read: boolean;
13	  createdAt: string;
14	  actionUrl?: string;
15	}
16	
17	export function useNotifications() {
18	  const [notifications, setNotifications] = useState<Notification[]>([]);
19	  const [unreadCount, setUnreadCount] = useState(0);
20	  const [isOpen, setIsOpen] = useState(false);
21	
22	  const loadNotifications = useCallback(async () => {
23	    try {
24	      const apiBase = import.meta.env.BASE_URL.replace(/\/$/, "");
25	      const res = await fetch(`${apiBase}/api/notifications`, {
26	        credentials: "include",
27	      });
28	      if (res.ok) {
29	        const data = await res.json();
30	        setNotifications(data.notifications || []);
31	        setUnreadCount(data.unreadCount || 0);
32	      }
33	    } catch (error) {
34	      console.error("Failed to load notifications:", error);
35	    }
36	  }, []);
37	
38	  const markAsRead = useCallback(async (notificationId: string) => {
39	    try {
40	      const apiBase = import.meta.env.BASE_URL.replace(/\/$/, "");
41	      await fetch(`${apiBase}/api/notifications/${notificationId}/read`, {
42	        method: "PATCH",
43	        credentials: "include",
44	      });
45	      setNotifications(prev =>
46	        prev.map(n => n.id === notificationId ? { ...n, read: true } : n)
47	      );
48	      setUnreadCount(prev => Math.max(0, prev - 1));
49	    } catch (error) {
50	      console.error("Failed to mark notification as read:", error);
51	    }
52	  }, []);
53	
54	  const markAllAsRead = useCallback(async () => {
55	    try {
56	      const apiBase = import.meta.env.BASE_URL.replace(/\/$/, "");
57	      await fetch(`${apiBase}/api/notifications/read-all`, {
58	        method: "PATCH",
59	        credentials: "include",
60	      });
61	      setNotifications(prev => prev.map(n => ({ ...n, read: true })));
62	      setUnreadCount(0);
63	    } catch (error) {
64	      console.error("Failed to mark all notifications as read:", error);
65	    }
66	  }, []);
67	
68	  const deleteNotification = useCallback(async (notificationId: string) => {
69	    try {
70	      const apiBase = import.meta.env.BASE_URL.replace(/\/$/, "");
71	      await fetch(`${apiBase}/api/notifications/${notificationId}`, {
72	        method: "DELETE",
73	        credentials: "include",
74	      });
75	      setNotifications(prev => prev.filter(n => n.id !== notificationId));
76	      const deleted = notifications.find(n => n.id === notificationId);
77	      if (deleted && !deleted.read) {
78	        setUnreadCount(prev => Math.max(0, prev - 1));
79	      }
80	    } catch (error) {
81	      console.error("Failed to delete notification:", error);
82	    }
83	  }, [notifications]);
84	
85	  useEffect(() => {
86	    loadNotifications();
87	    
88	    // Poll for new notifications every 30 seconds
89	    const interval = setInterval(loadNotifications, 30000);
90	    
91	    return () => clearInterval(interval);
92	  }, [loadNotifications]);
93	
94	  return {
95	    notifications,
96	    unreadCount,
97	    isOpen,
98	    setIsOpen,
99	    loadNotifications,
100	    markAsRead,
101	    markAllAsRead,
102	    deleteNotification,
103	  };
104	}
