112	): Notification {
113	  return {
114	    id: `local-${Date.now()}-${Math.random()}`,
115	    type,
116	    title,
117	    message,
118	    read: false,
119	    createdAt: new Date().toISOString(),
120	    ...metadata,
121	  };
122	}
