19	function apiBase(): string {
20	  return import.meta.env.BASE_URL.replace(/\/$/, "");
21	}
22	
23	async function apiFetch<T>(path: string, init?: RequestInit): Promise<T> {
24	  const res = await fetch(`${apiBase()}/api${path}`, {
25	    credentials: "include",
26	    headers: { "Content-Type": "application/json", ...(init?.headers ?? {}) },
27	    ...init,
28	  });
29	  if (!res.ok) {
30	    const text = await res.text().catch(() => res.statusText);
31	    throw new Error(text || `API error ${res.status}`);
32	  }
33	  if (res.status === 204) return undefined as T;
34	  return res.json() as Promise<T>;
35	}
