39	export async function listTasks(
40	  projectId: number,
41	  filter?: TaskFilter,
42	  sort?: TaskSort,
43	): Promise<RichTask[]> {
44	  const params = new URLSearchParams();
45	  if (filter?.status?.length) params.set("status", filter.status[0]);
46	  if (filter?.priority?.length) params.set("priority", filter.priority[0]);
47	  if (filter?.search) params.set("search", filter.search);
48	  if (filter?.dueBefore) params.set("dueBefore", filter.dueBefore);
49	  if (filter?.dueAfter) params.set("dueAfter", filter.dueAfter);
50	  if (filter?.assigneeIds?.length) params.set("assigneeId", String(filter.assigneeIds[0]));
51	
52	  const qs = params.toString();
53	  const tasks = await apiFetch<RichTask[]>(`/projects/${projectId}/tasks${qs ? `?${qs}` : ""}`);
54	
55	  // Client-side multi-filter (status/priority arrays, multiple assignees, tags)
56	  let result = tasks;
57	  if (filter?.status?.length) result = result.filter((t) => filter.status!.includes(t.status as never));
58	  if (filter?.priority?.length) result = result.filter((t) => filter.priority!.includes(t.priority as never));
59	  if (filter?.assigneeIds?.length) result = result.filter((t) => filter.assigneeIds!.some((id) => t.assigneeIds.includes(id)));
60	  if (filter?.tags?.length) result = result.filter((t) => filter.tags!.some((tag) => t.tags.includes(tag)));
61	
62	  // Client-side sort
63	  if (sort) {
64	    result = [...result].sort((a, b) => {
65	      const aVal = a[sort.field as keyof RichTask] as string | null;
66	      const bVal = b[sort.field as keyof RichTask] as string | null;
67	      if (aVal == null && bVal == null) return 0;
68	      if (aVal == null) return 1;
69	      if (bVal == null) return -1;
70	      const cmp = aVal < bVal ? -1 : aVal > bVal ? 1 : 0;
71	      return sort.direction === "asc" ? cmp : -cmp;
72	    });
73	  }
74	
75	  return result;
76	}
