172	interface RawComment {
173	  id: number;
174	  entityType: string;
175	  entityId: number | null;
176	  parentId: number | null;
177	  authorId: number;
178	  author: CollaboratorUser | null;
179	  content: string;
180	  resolved: boolean;
181	  createdAt: string;
182	  updatedAt: string;
183	  replies?: RawComment[];
184	}
185	
186	function rawToTaskComment(raw: RawComment): TaskComment {
187	  // Extract @mention user IDs from content (e.g. @[123])
188	  const mentions = [...raw.content.matchAll(/@\[(\d+)\]/g)].map((m) => parseInt(m[1], 10));
189	  return {
190	    id: raw.id,
191	    entityType: (raw.entityType as TaskComment["entityType"]) ?? "task",
192	    entityId: raw.entityId ?? 0,
193	    parentId: raw.parentId,
194	    author: raw.author ?? { id: raw.authorId, email: null, firstName: null, lastName: null, imageUrl: null },
195	    content: raw.content,
196	    mentions,
197	    createdAt: raw.createdAt,
198	    updatedAt: raw.updatedAt,
199	  };
200	}
201	
202	function flattenComments(roots: RawComment[]): TaskComment[] {
203	  const result: TaskComment[] = [];
204	  function walk(c: RawComment) {
205	    result.push(rawToTaskComment(c));
206	    (c.replies ?? []).forEach(walk);
207	  }
208	  roots.forEach(walk);
209	  return result;
210	}
